import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Настройка канала LINE","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/line.md","filePath":"ru/integrations/channels/line.md","lastUpdated":1792323081000}'),s={name:"ru/integrations/channels/line.md"};function r(l,e,i,h,g,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="настроика-канала-line" tabindex="-1">Настройка канала LINE <a class="header-anchor" href="#настроика-канала-line" aria-label="Permalink to &quot;Настройка канала LINE&quot;">​</a></h1><p>Подключите своего Bot в Memoh к официальному аккаунту LINE: пользователи добавляют связанный аккаунт в друзья и общаются с Bot один на один.</p><div class="warning custom-block"><p class="custom-block-title">Ограничения</p><ul><li>Только личные чаты. Сообщения из групп и многопользовательских комнат игнорируются — приглашать Bot в группу LINE бессмысленно.</li><li>Вывод — только обычный текст; Markdown не отображается.</li><li>Исходящие медиа ограничены изображениями PNG/JPEG. Изображения должны быть доступны из интернета по HTTPS и укладываться в лимиты LINE по размеру (10 МБ оригинал, 1 МБ превью); вложения, не являющиеся изображениями, отправить нельзя.</li><li>Входящие аудио, видео, стикеры и геопозиции не обрабатываются. Входящие изображения должны размещаться на серверах самого LINE (обычный случай для фото, отправленных из приложения).</li><li>Ответы приходят целыми сообщениями — LINE не поддерживает инкрементальный потоковый вывод, — а длинные ответы разбиваются на несколько сообщений по лимиту LINE в 5000 символов.</li><li>Ответы доставляются через <strong>Push API</strong> LINE, поэтому они расходуют квоту push-сообщений вашего тарифа LINE.</li></ul></div><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><p>LINE доставляет сообщения в Memoh через <strong>webhook</strong>, а серверы LINE также сами забирают исходящие изображения из вашего развёртывания, поэтому у Memoh должна быть публичная конечная точка HTTPS:</p><ul><li>Установите <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> в ваш публичный HTTPS origin (без пути, порта и внутренних адресов), или</li><li>Включите профиль Cloudflare Quick Tunnel в стеке server deploy — тогда Memoh получит публичный URL автоматически.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-создаите-канал-line-messaging-api" tabindex="-1">1. Создайте канал LINE Messaging API <a class="header-anchor" href="#_1-создаите-канал-line-messaging-api" aria-label="Permalink to &quot;1. Создайте канал LINE Messaging API&quot;">​</a></h3><p>В LINE Developers Console:</p><ol><li>Откройте <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>.</li><li>Создайте провайдера (или выберите существующего), затем создайте канал <strong>Messaging API</strong>. Он будет связан с официальным аккаунтом LINE.</li><li>В разделе <strong>Basic settings</strong> скопируйте <strong>Channel secret</strong>.</li><li>На вкладке <strong>Messaging API</strong> выпустите и скопируйте <strong>Channel access token</strong> (долгоживущий).</li></ol><blockquote><p>Официальное руководство: <a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">LINE Messaging API - Getting Started</a></p></blockquote><h3 id="_2-добавьте-канал-в-memoh" tabindex="-1">2. Добавьте канал в Memoh <a class="header-anchor" href="#_2-добавьте-канал-в-memoh" aria-label="Permalink to &quot;2. Добавьте канал в Memoh&quot;">​</a></h3><p>В Memoh:</p><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>LINE</strong>.</li><li>Вставьте <strong>Channel Secret</strong> и <strong>Channel Access Token</strong>.</li><li>Нажмите <strong>Save</strong> (или <strong>Save and Enable</strong>). URL обратного вызова webhook генерируется только после сохранения настроек.</li></ol><h3 id="_3-зарегистрируите-webhook" tabindex="-1">3. Зарегистрируйте webhook <a class="header-anchor" href="#_3-зарегистрируите-webhook" aria-label="Permalink to &quot;3. Зарегистрируйте webhook&quot;">​</a></h3><p>В Memoh после сохранения панель показывает доступный только для чтения <strong>WebHook Callback URL</strong> вида:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-public-base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>Зарегистрировать его можно двумя способами:</p><ul><li>Нажмите <strong>Set in LINE</strong> — Memoh запишет адрес webhook в ваш канал LINE напрямую через Messaging API. Сначала сохраните несохранённые изменения, иначе кнопка вернёт ошибку.</li><li>Или нажмите <strong>Copy</strong> и вручную вставьте URL в <strong>Messaging API → Webhook URL</strong> в LINE Developers Console.</li></ul><p>Затем в LINE Developers Console убедитесь, что для канала включён параметр <strong>Use webhook</strong>.</p><p>Memoh проверяет подписи входящих webhook по вашему <strong>Channel Secret</strong> и дедуплицирует события в течение 24 часов.</p><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Обязательное</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Channel Secret</strong></td><td>Да</td><td>Копируется из <strong>Basic settings</strong> канала Messaging API.</td></tr><tr><td><strong>Channel Access Token</strong></td><td>Да</td><td>Долгоживущий токен, выпущенный на вкладке <strong>Messaging API</strong>.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Добавьте связанный официальный аккаунт LINE в друзья, затем отправьте Bot <code>/help</code> в чате один на один. Bot ответит списком команд — это подтверждает, что канал работает.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите <strong>Channel Secret</strong> / <strong>Channel Access Token</strong> в той же панели и сохраните.</p><h2 id="faq" tabindex="-1">Частые вопросы <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Частые вопросы {#faq}&quot;">​</a></h2><h3 id="no-public-base-url" tabindex="-1">Панель предупреждает, что публичный базовый URL недоступен <a class="header-anchor" href="#no-public-base-url" aria-label="Permalink to &quot;Панель предупреждает, что публичный базовый URL недоступен {#no-public-base-url}&quot;">​</a></h3><p>Без публичного HTTPS origin невозможно построить URL обратного вызова webhook. Сначала настройте <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> или Cloudflare Quick Tunnel, как описано в предварительных условиях.</p>',30)])])}const b=t(s,[["render",r]]);export{p as __pageData,b as default};
